      "proposed_laureates": [
        "Mehran Kardar",
        "Yi-Cheng Zhang",
        "Kazumasa A. Takeuchi"
      ],
      "assessment": {
        "nobel_worthiness": "The KPZ framework identified a universal scaling theory for growing interfaces, a clear and influential example of nonequilibrium universality.",
        "attribution": "Kardar and Zhang made central theoretical contributions to the scaling framework; Takeuchi's experiments provided striking quantitative confirmation of its universal predictions.",
        "maturity": "The universality class is supported by extensive analytical, numerical, and experimental work across systems.",
        "uncertainties": [
          "The discovery's intellectual lineage includes the original KPZ authors, who are not among the credited names for this candidate."
        ]
      }
    },
